#!/bin/bash
# Ly Reloaded — merged one-file KISS installer for Slackware 15.0 x86_64.
# Contains the Ly binary and project assets internally; no TXZ/source archive needed.
# Ly is started by /etc/rc.d/rc.ly. No Ly guard is added to rc.4.
set -uo pipefail
umask 077

APP="Ly Reloaded — Slackware KISS Installer"
INITTAB=/etc/inittab
RC4=/etc/rc.d/rc.4
RCLY=/etc/rc.d/rc.ly
LYCONF=/etc/ly/config.ini
PAMFILE=/etc/pam.d/ly
STAMP=$(date +%Y%m%d-%H%M%S)
TMPROOT=$(mktemp -d /tmp/ly-kiss.XXXXXX) || exit 1
LOG="$TMPROOT/step.log"
trap 'rm -rf "$TMPROOT"' EXIT HUP INT TERM

say() { printf '%s\n' "$*"; }
need_root() {
    [ "$(id -u)" -eq 0 ] || { say "Run as root: su - and then ./ly-slackware-kiss.sh"; return 1; }
}
backup_once() {
    local file="$1" backup="${1}.pre-ly-kiss"
    if [ -e "$file" ] && [ ! -e "$backup" ]; then
        cp -a -- "$file" "$backup" || return 1
        say "Backup: $backup"
    elif [ -e "$backup" ]; then
        say "Existing backup preserved: $backup"
    fi
}
extract_payload() {
    base64 -d > "$TMPROOT/ly-payload.tar.gz" <<'LY_KISS_PAYLOAD_BASE64'
