LY_KISS_PAYLOAD_BASE64
    local got
    got=$(sha256sum "$TMPROOT/ly-payload.tar.gz" | awk '{print $1}')
    [ "$got" = "b0fb863b419fc8d9e6c032bf4b4169ef375ef33693c2da5f3919d5cf82cb1ff8" ] || { say "Error: embedded payload checksum does not match."; return 1; }
    mkdir -p "$TMPROOT/payload" || return 1
    tar -xzf "$TMPROOT/ly-payload.tar.gz" -C "$TMPROOT/payload" || return 1
    [ -x "$TMPROOT/payload/usr/bin/ly" ] || { say "Invalid payload: Ly binary is missing."; return 1; }
    [ -f "$TMPROOT/payload/etc/pam.d/ly" ] || { say "Invalid payload: PAM file is missing."; return 1; }
    say "Embedded payload verified and extracted."
}

step_check() {
    local bad=0
    command -v dialog >/dev/null 2>&1 || { say "MISSING: dialog."; bad=1; }
    command -v base64 >/dev/null 2>&1 || { say "MISSING: base64."; bad=1; }
    command -v tar >/dev/null 2>&1 || { say "MISSING: tar."; bad=1; }
    command -v python3 >/dev/null 2>&1 || { say "MISSING: python3."; bad=1; }
    [ -f "$INITTAB" ] || { say "LIPSEȘTE $INITTAB."; bad=1; }
    [ -f "$RC4" ] || { say "LIPSEȘTE $RC4."; bad=1; }
    [ -f /etc/pam.d/login ] || { say "MISSING: /etc/pam.d/login (required by the PAM include login rule)."; bad=1; }
    [ -x /sbin/agetty ] || { say "MISSING: /sbin/agetty."; bad=1; }
    if [ "$bad" -eq 0 ]; then
        say "Basic checks: OK."
        extract_payload || return 1
        /usr/bin/file "$TMPROOT/payload/usr/bin/ly" 2>/dev/null || true
        if command -v ldd >/dev/null 2>&1; then
            local lddout
            lddout=$(ldd "$TMPROOT/payload/usr/bin/ly" 2>&1)
            say "$lddout"
            if printf '%s\n' "$lddout" | grep -q 'not found'; then
                say "Dependențe dinamice lipsă; instalarea este oprită."
                return 1
            fi
        fi
    fi
    return "$bad"
}

step_install_binary_pam_assets() {
    extract_payload || return 1
    [ "$(uname -m)" = "x86_64" ] || { say "Unsupported architecture: $(uname -m); the embedded payload is x86_64."; return 1; }
    if command -v ldd >/dev/null 2>&1; then
        local depcheck
        depcheck=$(ldd "$TMPROOT/payload/usr/bin/ly" 2>&1)
        if printf '%s\n' "$depcheck" | grep -q 'not found'; then
            say "Missing dynamic dependencies; the binary will not be installed."
            say "$depcheck"
            return 1
        fi
    fi
    mkdir -p /usr/bin /etc/pam.d /etc/ly || return 1
    backup_once /usr/bin/ly || return 1
    install -m 0755 "$TMPROOT/payload/usr/bin/ly" /usr/bin/ly || return 1
    say "Installed binary: /usr/bin/ly"

    if [ -e "$PAMFILE" ]; then
        backup_once "$PAMFILE" || return 1
    fi
    install -m 0644 "$TMPROOT/payload/etc/pam.d/ly" "$PAMFILE" || return 1
    say "Instalat PAM: $PAMFILE"

    # Install helper scripts and language files only if missing; preserve user's config.ini.
    if [ -d "$TMPROOT/payload/etc/ly/lang" ]; then
        mkdir -p /etc/ly/lang || return 1
        local f base
        while IFS= read -r -d '' f; do
            base="${f#"$TMPROOT/payload/etc/ly/"}"
            if [ ! -e "/etc/ly/$base" ]; then
                install -D -m 0644 "$f" "/etc/ly/$base" || return 1
            fi
        done < <(find "$TMPROOT/payload/etc/ly/lang" -type f -print0)
    fi
    for f in wsetup.sh xsetup.sh; do
        if [ -f "$TMPROOT/payload/etc/ly/$f" ]; then
            if [ -e "/etc/ly/$f" ]; then
                if ! cmp -s "$TMPROOT/payload/etc/ly/$f" "/etc/ly/$f"; then
                    backup_once "/etc/ly/$f" || return 1
                    install -m 0755 "$TMPROOT/payload/etc/ly/$f" "/etc/ly/$f" || return 1
                    say "Updated helper: /etc/ly/$f"
                else
                    say "Helper already current: /etc/ly/$f"
                fi
            else
                install -m 0755 "$TMPROOT/payload/etc/ly/$f" "/etc/ly/$f" || return 1
                say "Installed helper: /etc/ly/$f"
            fi
        fi
    done
    if [ ! -f "$LYCONF" ]; then
        install -m 0644 "$TMPROOT/payload/etc/ly/config.ini" "$LYCONF" || return 1
        say "Installed initial configuration: $LYCONF"
    else
        backup_once "$LYCONF" || return 1
        say "Existing configuration was preserved."
    fi
}

step_config() {
    [ -f "$LYCONF" ] || { say "Not found: $LYCONF; install Ly files first."; return 1; }
    backup_once "$LYCONF" || return 1
    local tmp="$TMPROOT/config.ini"
    awk '
      BEGIN {
        val["path"]="/sbin:/bin:/usr/local/sbin:/usr/local/bin:/usr/bin:/usr/sbin"
        val["service_name"]="ly"
        val["tty"]="2"
        val["x_cmd"]="/usr/bin/X"
        val["x_cmd_setup"]="/etc/ly/xsetup.sh"
        val["xauth_cmd"]="/usr/bin/xauth"
        val["xsessions"]="/usr/share/xsessions"
        val["shutdown_cmd"]="/sbin/poweroff"
        val["restart_cmd"]="/sbin/reboot"
        n=split("path service_name tty x_cmd x_cmd_setup xauth_cmd xsessions shutdown_cmd restart_cmd", keys, " ")
        for (i=1; i<=n; i++) valset[keys[i]]=1
      }
      {
        line=$0
        key=line
        sub(/^[[:space:]]*#[[:space:]]*/, "", key)
        sub(/^[[:space:]]*/, "", key)
        split(key, parts, "=")
        k=parts[1]
        gsub(/[[:space:]]/, "", k)
        if (k in valset) {
          print k " = " val[k]
          seen[k]=1
          next
        }
        print line
      }
      END {
        n=split("path service_name tty x_cmd x_cmd_setup xauth_cmd xsessions shutdown_cmd restart_cmd", keys, " ")
        for (i=1; i<=n; i++) if (!(keys[i] in seen)) print keys[i] " = " val[keys[i]]
      }' "$LYCONF" > "$tmp" || return 1
    if ! cmp -s "$LYCONF" "$tmp"; then
        cat "$tmp" > "$LYCONF" || return 1
        say "Configured Ly session, PATH, XFCE session discovery, and F1/F2 commands."
    else
        say "Ly session, PATH, and F1/F2 settings were already configured."
    fi
}
step_rcly() {
    [ -x /usr/bin/ly ] || { say "Missing /usr/bin/ly; instalează întâi binarul."; return 1; }
    cat > "$TMPROOT/rc.ly" <<'RC_LY'
#!/bin/sh
# Ly Reloaded Slackware integration.
# Started by /etc/inittab; init manages respawn.
GETTY=/sbin/agetty
exec "$GETTY" -L -n -l /usr/bin/ly 38400 tty2 linux
RC_LY
    install -m 0755 "$TMPROOT/rc.ly" "$RCLY" || return 1
    say "Creat/updated $RCLY."
}

step_inittab() {
    [ -f "$INITTAB" ] || { say "Not found: $INITTAB"; return 1; }
    backup_once "$INITTAB" || return 1
    local tmp="$TMPROOT/inittab"

    # Change only the three Ly-related entries. Do not run `init q` here:
    # rereading inittab while Xfce is running can interrupt the session.
    awk '
      /^[[:space:]]*#/ {
        line=$0
        sub(/^[[:space:]]*/, "", line)
        if (line ~ /^#?[[:space:]]*c2:[^:]*:respawn:/ && line ~ /agetty/ && line ~ /tty2([[:space:]]|$)/) next
        if (line ~ /^#?[[:space:]]*x1:[^:]*:respawn:/ && line ~ /\/etc\/rc\.d\/rc\.4([[:space:]]|$)/) next
        if (line ~ /^#?[[:space:]]*x2:[^:]*:respawn:/ && line ~ /\/etc\/rc\.d\/rc\.ly([[:space:]]|$)/) next
        print
        next
      }
      {
        if ($0 ~ /^[[:space:]]*c2:[^:]*:respawn:/ && $0 ~ /agetty/ && $0 ~ /tty2([[:space:]]|$)/) next
        if ($0 ~ /^[[:space:]]*x1:[^:]*:respawn:/ && $0 ~ /\/etc\/rc\.d\/rc\.4([[:space:]]|$)/) next
        if ($0 ~ /^[[:space:]]*x2:[^:]*:respawn:/ && $0 ~ /\/etc\/rc\.d\/rc\.ly([[:space:]]|$)/) next
        print
      }
      END {
        print "#c2:12345:respawn:/sbin/agetty 38400 tty2 linux"
        print "#x1:4:respawn:/etc/rc.d/rc.4"
        print "x2:4:respawn:/etc/rc.d/rc.ly"
      }
    ' "$INITTAB" > "$tmp" || return 1

    chmod --reference="$INITTAB" "$tmp" 2>/dev/null || chmod 0644 "$tmp"
    if ! cmp -s "$INITTAB" "$tmp"; then
        cat "$tmp" > "$INITTAB" || return 1
        say "Updated only the Ly entries in $INITTAB."
    else
        say "$INITTAB already has the required Ly entries."
    fi
    say "No init q executed; the running graphical session is left alone."
}
step_rc4() {
    [ -f "$RC4" ] || { say "Not found: $RC4."; return 1; }
    python3 - "$RC4" "$STAMP" <<'PY_RC4'
import os, re, shutil, subprocess, sys, tempfile
path, stamp = sys.argv[1], sys.argv[2]
with open(path, "r", encoding="utf-8", errors="surrogateescape") as f:
    original = f.readlines()
lines = list(original)
# Remove labels left by earlier test scripts while retaining commented content.
normalized = []
for line in lines:
    stripped = line.lstrip()
    if stripped.startswith("# ly-reloaded: Ly owns the graphical login"):
        # Remove the legacy marker; its active exit guard is removed below.
        continue
    for marker in ("# ly-rc4-fix: ", "# ly-slackware-setup: ", "# ly-slackware-kiss: ", "# ly-reloaded: "):
        if stripped.startswith(marker):
            indent = line[:len(line) - len(stripped)]
            line = indent + "# " + stripped[len(marker):]
            break
    normalized.append(line)
lines = normalized
out, changed, found, removed_guard = [], 0, [], 0
dm = re.compile(r"(?i)(?:/usr/bin/(?:gdm|kdm|sddm|xdm|lxdm|lightdm|slim)|/usr/sbin/(?:gdm|kdm|sddm|xdm|lxdm|lightdm|slim)|/opt/kde/bin/kdm|/usr/X11R6/bin/xdm|\b(?:gdm|kdm|sddm|xdm|lxdm|lightdm|slim)\b)")

# Remove only a recognized legacy Ly early-exit guard (if it exits immediately).
i = 0
while i < len(lines):
    s = lines[i].strip()
    if not s.startswith("#") and re.match(r"^if\b", s) and re.search(r"/usr/bin/ly\b", s):
        j, depth = i, 0
        while j < len(lines):
            t = lines[j].strip()
            if not t.startswith("#"):
                if re.match(r"^if\b", t): depth += 1
                elif re.match(r"^fi\b", t):
                    depth -= 1
                    if depth == 0:
                        j += 1
                        break
            j += 1
        block = lines[i:j]
        if depth == 0 and any(re.match(r"\s*exit\s+0\s*$", x) for x in block):
            del lines[i:j]
            removed_guard += 1
            continue
    i += 1

i = 0
while i < len(lines):
    line, s = lines[i], lines[i].strip()
    if not s.startswith("#") and re.match(r"^if\b", s) and dm.search(s):
        j, depth = i, 0
        while j < len(lines):
            t = lines[j].strip()
            if not t.startswith("#"):
                if re.match(r"^if\b", t): depth += 1
                elif re.match(r"^fi\b", t):
                    depth -= 1
                    if depth == 0:
                        j += 1
                        break
            j += 1
        if depth == 0:
            found.append(s)
            for b in lines[i:j]:
                out.append("# disabled display-manager: " + b if b.strip() else b)
            changed += 1
            i = j
            continue
    if not s.startswith("#") and re.match(r"^(?:exec\s+)?/(?:usr/bin/(?:gdm|kdm|sddm|xdm|lxdm|lightdm|slim)|usr/sbin/(?:gdm|kdm|sddm|xdm|lxdm|lightdm|slim)|opt/kde/bin/kdm|usr/X11R6/bin/xdm)(?:\s|$)", s):
        out.append("# disabled display-manager command: " + line)
        changed += 1
        i += 1
        continue
    out.append(line)
    i += 1
new = "".join(out)
fd, candidate = tempfile.mkstemp(prefix=".rc.4.ly-kiss.", dir=os.path.dirname(path) or ".")
try:
    with os.fdopen(fd, "w", encoding="utf-8", errors="surrogateescape") as f:
        f.write(new)
    os.chmod(candidate, os.stat(path).st_mode)
    check = subprocess.run(["/bin/sh", "-n", candidate], capture_output=True, text=True)
    if check.returncode:
        print("ERROR: invalid rc.4 syntax; original file was preserved.", file=sys.stderr)
        print(check.stderr, file=sys.stderr)
        sys.exit(1)
    if new != "".join(original):
        backup = path + ".pre-ly-kiss." + stamp
        shutil.copy2(path, backup)
        os.replace(candidate, path)
    print("Display-manager blocks commented: " + str(changed))
    for item in found: print("  - " + item)
    print("Legacy Ly exit guard removed: " + str(removed_guard))
    print("rc.4 syntax: OK")
finally:
    if os.path.exists(candidate):
        os.unlink(candidate)
PY_RC4
}

step_cleanup_install() {
    if [ ! -d /install ] || [ -L /install ] || mountpoint -q /install 2>/dev/null; then
        say "Not found: director /install sigur de curățat."
        return 0
    fi
    if [ "$(find /install -mindepth 1 -maxdepth 1 2>/dev/null | wc -l | tr -d ' ')" != 2 ] ||
       [ ! -f /install/doinst.sh ] || [ -L /install/doinst.sh ] ||
       [ ! -f /install/slack-desc ] || [ -L /install/slack-desc ]; then
        say "/install does not match the known residue exactly; it was left untouched (safe skip)."
        return 0
    fi
    local a b
    a=$(sha256sum /install/doinst.sh | awk '{print $1}')
    b=$(sha256sum /install/slack-desc | awk '{print $1}')
    if [ "$a" = "c68420775e0bed45965a54012f939c132193298e71d71074753584d28543df14" ] &&
       [ "$b" = "bb6d52b3589a670c118742e8af447ed1621dce547f918324def9b9300ca26c43" ]; then
        rm -f /install/doinst.sh /install/slack-desc && rmdir /install || return 1
        say "Removed the exactly identified /install residue."
    else
        say "/install does not match the known checksums; it was left untouched (safe skip)."
        return 0
    fi
}

step_verify() {
    local bad=0 status
    [ -x /usr/bin/ly ] && say "OK: /usr/bin/ly" || { say "LIPSEȘTE /usr/bin/ly"; bad=1; }
    [ -f "$PAMFILE" ] && say "OK: $PAMFILE" || { say "LIPSEȘTE $PAMFILE"; bad=1; }
    [ -x "$RCLY" ] && say "OK: $RCLY" || { say "LIPSEȘTE $RCLY"; bad=1; }
    [ -f "$INITTAB" ] && say "OK: $INITTAB" || { say "LIPSEȘTE $INITTAB"; bad=1; }
    if awk '!/^[[:space:]]*#/ && /ly-slackware-kiss|ly-reloaded|\/usr\/bin\/ly|\/etc\/rc\.d\/rc\.ly/ { print; bad=1 } END { exit bad ? 0 : 1 }' "$RC4"; then
        say "WARNING: active Ly references remain in rc.4"; bad=1
    else
        say "OK: no active Ly references in rc.4"
    fi
    /bin/sh -n "$RC4"
    status=$?
    say "rc.4 syntax — echo \$?: $status"
    [ "$status" -eq 0 ] || bad=1
    return "$bad"
}

show_result() {
    local title="$1" status="$2"
    printf '\nExit status (echo $?): %s\n' "$status" >> "$LOG"
    dialog --title "$title — echo $? = $status" --textbox "$LOG" 22 78
}
run_step() {
    local title="$1"; shift
    : > "$LOG"
    "$@" >"$LOG" 2>&1
    local status=$?
    show_result "$title" "$status"
    return "$status"
}
run_all() {
    local total=0 status i
    local -a funcs=(step_check step_install_binary_pam_assets step_config step_rcly step_inittab step_rc4 step_cleanup_install step_verify)
    local -a titles=("1. Verificare preliminară" "2. Instalare binar, PAM și fișiere" "3. Configurare F1/F2" "4. Creare rc.ly" "5. Configurare inittab" "6. Detectare DM în rc.4" "7. Curățare sigură /install" "8. Final verification")
    for i in "${!funcs[@]}"; do
        run_step "${titles[$i]}" "${funcs[$i]}"
        status=$?
        [ "$status" -eq 0 ] || total=1
        if [ "$status" -ne 0 ]; then
            dialog --title "Step failed — cod $status" --yesno "Step '${titles[$i]}' returned exit code $status.\n\nContinue with the remaining steps?" 10 68 || break
        fi
    done
    : > "$LOG"
    printf 'Combined exit status (echo $?): %s\n' "$total" > "$LOG"
    dialog --title "Overall result" --textbox "$LOG" 8 60
    return "$total"
}

if ! need_root; then exit 1; fi
if ! command -v dialog >/dev/null 2>&1; then
    echo "Error: dialog is not installed."
    exit 1
fi

while true; do
    choice=$(dialog --clear --stdout --title "$APP" \
      --menu "One script, all required files embedded.\nEach step displays its exit status.\n\nRecommended: run the preflight check first." \
      21 80 10 \
      1 "Preflight checks and dependencies" \
      2 "Install Ly binary + PAM + support files" \
      3 "Configure F1/F2 commands" \
      4 "Create / update rc.ly" \
      5 "Configure /etc/inittab" \
      6 "Detect and comment out display managers in rc.4" \
      7 "Safely clean exact known /install residue (otherwise skip)" \
      8 "Final verification" \
      9 "Run all steps" \
      0 "Exit") || exit 0
    case "$choice" in
      1) run_step "Verificare preliminară" step_check ;;
      2) run_step "Instalare binar, PAM și fișiere" step_install_binary_pam_assets ;;
      3) run_step "Configurare F1/F2" step_config ;;
      4) run_step "Creare rc.ly" step_rcly ;;
      5) run_step "Configurare inittab" step_inittab ;;
      6) run_step "Detectare DM în rc.4" step_rc4 ;;
      7) run_step "Curățare /install" step_cleanup_install ;;
      8) run_step "Final verification" step_verify ;;
      9) run_all ;;
      0) clear; exit 0 ;;
    esac
done
